extractions = ()
for d in context:
    res = llm_query("You are given a single document. Identify if it contains or describes a specific academic paper that matches ALL of the following clues. If yes, extract structured details; if not, return NO_MATCH.\n\nClues to match:\n- Published in the 2010s.\n- The author used a sample representing around 20% of the usual resident population of a country, based on the reference date of a Population and Housing Census.\n- The sample comprised approximately 1.7 million employed individuals.\n- The paper presents findings of a multinomial logistic regression.\n- The same author also published another paper in the same year; the two papers share at least one keyword.\n\nInstructions:\n- Search the document carefully for mentions of the above. The document may include an abstract, methods, sample description, or a publication list/CV.\n- If a match is found, provide the following fields exactly once, each on its own line with the label followed by a colon:\nTitle:\nAuthor(s):\nYear:\nCountry:\nSample description:\nSample size (employed):\nMethod:\nKeywords:\nPublication name:\nPublication type:\nEvidence quotes:\nSame-year paper (title):\nShared keyword(s):\nConfidence (0-1):\n- If no match, output only: NO_MATCH\n\nDocument begins:\nBEGIN_DOCUMENT\n" + d + "\nEND_DOCUMENT")
    extractions = extractions + (res,)

aggregated = "\n\n---\n\n".join(extractions)

final_answer = llm_query("You will be given several extractions from different documents. Your task is to determine the publication venue (journal, proceedings, or series) for the single paper that best matches ALL of the following constraints:\n- It is a paper published in the 2010s.\n- The author used a sample representing around 20% of the usual resident population of a country, based on the reference date of a Population and Housing Census.\n- The sample comprised approximately 1.7 million employed individuals.\n- The paper presents the findings of a multinomial logistic regression.\n- The author also published another paper in the same year, which shares a keyword with this one.\n\nExtractions:\n" + aggregated + "\n\nInstructions:\n- Ignore any extraction that is NO_MATCH or that does not mention both the ~20% usual resident population and ~1.7 million employed individuals and multinomial logistic regression.\n- Among remaining candidates, choose the one with the strongest alignment (explicit mentions and supporting quotes) and highest confidence.\n- Return ONLY the name of the publication venue (e.g., the journal/proceedings/series name). Do not include title, year, author, or anything else.\n- If there are multiple publication venue names in the chosen extraction (e.g., journal + publisher), return only the journal/proceedings name.\n- Output just the venue name, nothing else.")
return_result(final_answer)